// internal/distributed/proxy/httpserver/timeout_middleware.go line 183-186
func timeoutMiddleware(handler gin.HandlerFunc) gin.HandlerFunc {
    ...
    timeout := paramtable.Get().HTTPCfg.RequestTimeoutMs.GetAsDuration(time.Millisecond)
    timeoutSecond, err := strconv.ParseInt(gCtx.Request.Header.Get(mhttp.HTTPHeaderRequestTimeout), 10, 64)
    if err == nil {
        timeout = time.Duration(timeoutSecond) * time.Second
    }
    ...
}

The code uses strconv.ParseInt to parse Request-Timeout header value. When parsing fails (returns err), the code simply ignores the error and falls back to default timeout. Invalid values like "abc" are silently accepted rather than returning a 400 error.
